#include <cstdint>
#include <map>
#include <string>

// Ring: hash position -> server name. Ordered map gives clockwise lookup.
using Ring = std::map<uint64_t, std::string>;

std::string owner(const Ring& ring, uint64_t keyHash) {
    if (ring.empty()) return {};
    auto it = ring.lower_bound(keyHash);      // first position >= keyHash
    if (it == ring.end()) it = ring.begin();  // wrap around
    return it->second;
}

// Adding a server inserts its virtual nodes. Only keys whose hash lies
// between each new node and its predecessor change owner.
void addServer(Ring& ring, const std::string& name, int replicas,
               uint64_t (*hashFn)(const std::string&)) {
    for (int i = 0; i < replicas; ++i)
        ring[hashFn(name + "-" + std::to_string(i))] = name;
}
```

